/**
 * The first dependency cycle a depth-first search finds, starting from each task
 * in ascending name order and walking each task's dependencies in ascending name
 * order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle's names, from the re-entered task through the
 *   search stack and back to a repeat of it, or null when there is none.
 */
export function findCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    const deps = [...tasks.get(name).needs].sort()
    for (const dep of deps) {
      const status = state.get(dep)
      if (status === 'active') {
        const start = stack.indexOf(dep)
        return [...stack.slice(start), dep]
      }
      if (status === undefined) {
        const found = visit(dep)
        if (found) return found
      }
    }
    state.set(name, 'done')
    stack.pop()
    return null
  }

  for (const name of names) {
    if (!state.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted. Assumes the graph has no cycle; call
 * `findCycle` first to be sure.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 */
export function order(tasks) {
  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    if (ready.length === 0) break
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
"}

