/** The command: `order`, `show <name>`, `files <name>`, `digest <path>...` and `plan <snapshot>`. */

import { existsSync, readFileSync } from 'node:fs'
import { digestBytes } from './digest.js'
import { findCycle, order } from './graph.js'
import { parse, ParseError, splitLines } from './parse.js'

const USAGE = 'usage: cli.js order|show <name>|files <name>|digest <path>...|plan <snapshot>'
const DIGEST = /^[0-9a-f]{8}$/

/** Report one failure the way the specification words it, and stop. */
function fail(message, code = 2) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(code)
}

/** One `show`/`files` field, with `-` standing for an empty list. */
function field(label, values) {
  return `${label}: ${values.length === 0 ? '-' : [...values].sort().join(' ')}`
}

/** Report a dependency cycle and stop, exiting 3. */
function failCycle(cycle) {
  process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
  process.exit(3)
}

/**
 * Parse a digest snapshot file.
 * @param {string} path - the snapshot's path.
 * @returns {Map<string, string>} the recorded digest by path.
 */
function readSnapshot(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    fail(`cannot read snapshot ${path}`)
  }
  const digests = new Map()
  const lines = splitLines(text)
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words.length !== 2) fail(`${path}: line ${line}: expected <path> <digest>`)
    const [entry, digest] = words
    if (!DIGEST.test(digest)) fail(`${path}: line ${line}: invalid digest ${digest}`)
    if (digests.has(entry)) fail(`${path}: line ${line}: path ${entry} is recorded twice`)
    digests.set(entry, digest)
  }
  return digests
}

/** The watched paths of a task: its reads and writes together, deduplicated and ascending. */
function watched(task) {
  return [...new Set([...task.reads, ...task.writes])].sort()
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { order: 1, show: 2, files: 2, plan: 2 }
if (mode === 'digest' ? argv.length < 2 : argv.length !== arity[mode]) fail(USAGE)

let tasks
try {
  tasks = parse(splitLines(readFileSync(0, 'utf8')))
} catch (error) {
  if (!(error instanceof ParseError)) throw error
  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
}

const out = []
if (mode === 'order') {
  const cycle = findCycle(tasks)
  if (cycle) failCycle(cycle)
  for (const name of order(tasks)) out.push(name)
} else if (mode === 'show') {
  const task = tasks.get(argv[1])
  if (task === undefined) fail(`unknown task ${argv[1]}`)
  out.push(`${task.name}: ${task.command}`)
  out.push(field('needs', task.needs))
} else if (mode === 'files') {
  const task = tasks.get(argv[1])
  if (task === undefined) fail(`unknown task ${argv[1]}`)
  out.push(field('reads', task.reads))
  out.push(field('writes', task.writes))
} else if (mode === 'plan') {
  const snapshot = readSnapshot(argv[1])
  const cycle = findCycle(tasks)
  if (cycle) failCycle(cycle)
  const runNames = order(tasks)
  const runs = new Map()
  let runCount = 0
  let skipCount = 0
  for (const name of runNames) {
    const task = tasks.get(name)
    let reason = null
    for (const path of watched(task)) {
      const recorded = snapshot.get(path)
      if (recorded === undefined) {
        reason = `new ${path}`
        break
      }
      if (!existsSync(path)) {
        reason = `missing ${path}`
        break
      }
      const actual = digestBytes(readFileSync(path))
      if (actual !== recorded) {
        reason = `changed ${path}`
        break
      }
    }
    if (reason === null) {
      const runningDeps = [...task.needs].filter(dep => runs.get(dep)).sort()
      if (runningDeps.length > 0) reason = `needs ${runningDeps[0]}`
    }
    if (reason === null) {
      runs.set(name, false)
      skipCount += 1
      out.push(`skip ${name}`)
    } else {
      runs.set(name, true)
      runCount += 1
      out.push(`run ${name} ${reason}`)
    }
  }
  out.push(`total run=${runCount} skip=${skipCount}`)
} else {
  for (const path of argv.slice(1)) {
    out.push(`${path} ${existsSync(path) ? digestBytes(readFileSync(path)) : 'missing'}`)
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

