export function findCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const state = new Map()

  for (const start of names) {
    if (state.has(start)) continue
    // An explicit stack of frames, each a name and the sorted dependencies left to visit,
    // so a long chain of dependencies cannot overflow the call stack.
    const stack = [start]
    const frames = [{ deps: [...tasks.get(start).needs].sort(), index: 0 }]
    state.set(start, 'active')
    while (stack.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.index >= frame.deps.length) {
        state.set(stack.pop(), 'done')
        frames.pop()
        continue
      }
      const dep = frame.deps[frame.index]
      frame.index += 1
      const status = state.get(dep)
      if (status === 'active') {
        const at = stack.indexOf(dep)
        return [...stack.slice(at), dep]
      }
      if (status === undefined) {
        state.set(dep, 'active')
        stack.push(dep)
        frames.push({ deps: [...tasks.get(dep).needs].sort(), index: 0 })
      }
    }
  }
  return null
}

