  }
  return h.toString(16).padStart(8, '0')
}

function pick(rand, arr) { return arr[Math.floor(rand() * arr.length)] }

function buildScenario(rand) {
  const nTasks = 2 + Math.floor(rand() * 4)
  const names = []
  for (let i = 0; i < nTasks; i++) names.push('t' + i)
  const needs = new Map(names.map(n => [n, []]))
  // build a DAG: only allow needs pointing to earlier-indexed tasks to avoid cycle
  for (let i = 0; i < nTasks; i++) {
    for (let j = 0; j < i; j++) {
      if (rand() < 0.35) needs.get(names[i]).push(names[j])
    }
  }
  const filePaths = ['f0.txt','f1.txt','f2.txt','f3.txt','f4.txt']
  const reads = new Map(names.map(n => [n, []]))
  const writes = new Map(names.map(n => [n, []]))
  for (const n of names) {
    for (const f of filePaths) {
      if (rand() < 0.3) reads.get(n).push(f)
      if (rand() < 0.15) writes.get(n).push(f)
    }
  }
  return { names, needs, reads, writes, filePaths }
}

function writeTaskFile(scn) {
  const lines = []
  for (const n of scn.names) lines.push(`task ${n} echo ${n}`)
  for (const n of scn.names) {
    if (scn.needs.get(n).length) lines.push(`needs ${n} ${scn.needs.get(n).join(' ')}`)
    if (scn.reads.get(n).length) lines.push(`reads ${n} ${scn.reads.get(n).join(' ')}`)
    if (scn.writes.get(n).length) lines.push(`writes ${n} ${scn.writes.get(n).join(' ')}`)
  }
  return lines.join('\n') + '\n'
}

function setupWorkspace(rand, scn) {
  rmSync(ROOT, { recursive: true, force: true })
  mkdirSync(ROOT, { recursive: true })
  const actualDigest = new Map()
  for (const f of scn.filePaths) {
    if (rand() < 0.7) {
      const content = 'content-' + Math.floor(rand() * 1000)
      writeFileSync(path.join(ROOT, f), content)
      actualDigest.set(f, fnv1a(Buffer.from(content)))
    }
    // else file missing
  }
  return actualDigest
}

