    const watched = [...new Set([...scn.reads.get(name), ...scn.writes.get(name)])].sort()
    let reason = null
    for (const p of watched) {
      if (!recorded.has(p)) { reason = `new ${p}`; break }
      if (!actualDigest.has(p)) { reason = `missing ${p}`; break }
      if (actualDigest.get(p) !== recorded.get(p)) { reason = `changed ${p}`; break }
    }
    if (reason === null) {
      const runningDeps = scn.needs.get(name).filter(d => runs.get(d)).sort()
      if (runningDeps.length) reason = `needs ${runningDeps[0]}`
    }
    if (reason === null) { runs.set(name,false); s++; outLines.push(`skip ${name}`) }
    else { runs.set(name,true); r++; outLines.push(`run ${name} ${reason}`) }
  }
  outLines.push(`total run=${r} skip=${s}`)
  return outLines.join('\n') + '\n'
}

